  game.resultNote = "Twoje statystyki z tej rundy.";
  game.rankingPointsEarnedRun = 0;
  game.rankingShip = null;
  clearGameResultTimers();
  game.coopPartyId = "";
  game.coopSessionId = "";
  game.coopHostProfileId = "";
  game.coopIsHost = false;
